import fnmatch
import pathlib
import tomllib
from dataclasses import dataclass
from typing import Any



# @spec FR-032
# @spec CR-002


class DispatchBriefPolicyError(ValueError):
    """The brief requests scope or capability outside repository authority."""


@dataclass(frozen=True)
class AuthorizedDispatch:
    owned_scope: tuple[str, ...]
    capabilities: tuple[str, ...]
    verification_commands: tuple[str, ...]


def _strings(
    value: Any,
    label: str,
    *,
    require_nonempty: bool,
) -> tuple[str, ...]:
    if not isinstance(value, list) or (require_nonempty and not value):
        suffix = " must be non-empty" if require_nonempty else " must be a list"
        raise DispatchBriefPolicyError(f"repository profile {label}{suffix}")
    if not all(isinstance(item, str) and item.strip() for item in value):
        raise DispatchBriefPolicyError(
            f"repository profile {label} must contain non-empty strings"
        )
    return tuple(value)


def _static_prefix(pattern: str) -> tuple[str, ...]:
    normalized = pathlib.PurePosixPath(pattern)
    parts: list[str] = []
    for part in normalized.parts:
        if any(token in part for token in ("*", "?", "[")):
            break
        parts.append(part)
    return tuple(parts)


def _validate_relative_pattern(pattern: str, label: str, *, name_only: bool = False) -> None:
    path = pathlib.PurePosixPath(pattern)
    if (
        not pattern
        or pattern.strip() != pattern
        or path.is_absolute()
        or ".." in path.parts
        or pattern in {".", "./"}
        or "\\" in pattern
    ):
        raise DispatchBriefPolicyError(f"{label} must be a safe repository-relative pattern")
    if not _static_prefix(pattern) and not (name_only and "/" not in pattern):
        raise DispatchBriefPolicyError(f"{label} must have a concrete path prefix")


def _contained_by(scope: str, allowed: str) -> bool:
    scope_prefix = _static_prefix(scope)
    allowed_prefix = _static_prefix(allowed)
    return scope_prefix[: len(allowed_prefix)] == allowed_prefix


def _patterns_intersect(left: str, right: str) -> bool:
    left_prefix = _static_prefix(left)
    right_prefix = _static_prefix(right)
    shortest = min(len(left_prefix), len(right_prefix))
    return left_prefix[:shortest] == right_prefix[:shortest]


def _protects(protected: str, owned: str) -> bool:
    """A slash-free protected pattern names a file at any depth, like `.gitignore`."""
    if "/" not in protected and any(
        fnmatch.fnmatchcase(part, protected) for part in _static_prefix(owned)
    ):
        return True
    return bool(_static_prefix(protected)) and _patterns_intersect(owned, protected)


def authorize_dispatch_brief(
    repo_root: pathlib.Path,
    brief: DispatchBrief,
) -> AuthorizedDispatch:
    """Authorize exact brief scope and capabilities against the local profile."""
    profile_path = pathlib.Path(repo_root) / ".mir" / "repo-profile.toml"
    try:
        with profile_path.open("rb") as handle:
            profile = tomllib.load(handle)
    except (OSError, tomllib.TOMLDecodeError) as error:
        raise DispatchBriefPolicyError(
            "repository profile is missing or invalid"
        ) from error

    paths = profile.get("paths")
    execution = profile.get("execution")
    if not isinstance(paths, dict) or not isinstance(execution, dict):
        raise DispatchBriefPolicyError(
            "repository profile paths and execution sections are required"
        )
    allowed_paths = _strings(
        paths.get("code_paths"),
        "paths.code_paths",
        require_nonempty=True,
    )
    protected_paths = _strings(
        paths.get("protected_paths", []),
        "paths.protected_paths",
        require_nonempty=False,
    )
    allowed_capabilities = _strings(
        execution.get("codex_allowed_modes"),
        "execution.codex_allowed_modes",
        require_nonempty=True,
    )
    blocked_capabilities = _strings(
        execution.get("codex_blocked_modes", []),
        "execution.codex_blocked_modes",
        require_nonempty=False,
    )

    for pattern in (*allowed_paths, *brief.owned_scope):
        _validate_relative_pattern(pattern, "dispatch path")
    for pattern in protected_paths:
        _validate_relative_pattern(pattern, "dispatch path", name_only=True)
    for owned in brief.owned_scope:
        if any(_protects(protected, owned) for protected in protected_paths):
            raise DispatchBriefPolicyError(
                f"owned_scope intersects protected path: {owned}"
            )
        if not any(_contained_by(owned, allowed) for allowed in allowed_paths):
            raise DispatchBriefPolicyError(
                f"owned_scope is not delegable by repository profile: {owned}"
            )

    blocked = sorted(set(brief.capabilities) & set(blocked_capabilities))
    unknown = sorted(set(brief.capabilities) - set(allowed_capabilities))
    if blocked:
        raise DispatchBriefPolicyError(
            f"blocked dispatch capabilities: {', '.join(blocked)}"
        )
    if unknown:
        raise DispatchBriefPolicyError(
            f"unapproved dispatch capabilities: {', '.join(unknown)}"
        )

    return AuthorizedDispatch(
        owned_scope=brief.owned_scope,
        capabilities=brief.capabilities,
        verification_commands=brief.verification_commands,
    )


__all__ = (
    "AuthorizedDispatch",
    "DispatchBriefPolicyError",
    "authorize_dispatch_brief",
)

def _load_authorized_brief(path: pathlib.Path, repo_root: pathlib.Path):
    """Load the typed DispatchBrief and authorize it against .mir/repo-profile.toml."""
    from mir.core.conductor.dispatch_brief import load_dispatch_brief  # noqa: PLC0415
    from tools.mir_executor.brief_policy import authorize_dispatch_brief  # noqa: PLC0415

    brief = load_dispatch_brief(path)
    if not brief.expanded_goal.strip():
        raise ValueError("DispatchBrief expanded_goal must be non-empty")
    return brief, authorize_dispatch_brief(repo_root, brief)

def validate_brief(brief: pathlib.Path | str, repo_root: pathlib.Path):
    """Keep the typed, profile-authorized DispatchBrief; plain prompts pass through."""
    if isinstance(brief, pathlib.Path):
        return _load_authorized_brief(brief, repo_root)[0]
    return None

def render_brief(validated, repo_root: pathlib.Path) -> str | None:
    """Give the worktree the rendered brief (scope, capabilities, stop conditions)."""
    if validated is None:
        return None
    from mir.core.conductor.dispatch_brief import render_dispatch_brief  # noqa: PLC0415

    return render_dispatch_brief(validated)

def _verifier_ids(commands: list[str], repo_root: pathlib.Path) -> list[str]:
    """Map a command string equal to a registered verifier argv onto its ID.

    `scripts/loop_driver.sh` passes `tasks/tdd.json` command strings. Only exact argv
    matches are mapped; anything else stays and the merge gate rejects it.
    """
    verifiers = local_config(repo_root).get("verifiers", {})
    by_argv = {tuple(argv): verifier_id for verifier_id, argv in verifiers.items()}
    mapped = []
    for command in commands:
        if command not in verifiers:
            try:
                command = by_argv.get(tuple(shlex.split(command)), command)
            except ValueError:
                pass
        mapped.append(command)
    return mapped

def pre_execute(args: argparse.Namespace, repo_root: pathlib.Path) -> None:
    """Bind a dispatch to its authorized brief before any job or worktree exists."""
    supplied_verifiers = _verifier_ids(list(getattr(args, "verify_cmds", None) or ()), repo_root)
    if supplied_verifiers:
        args.verify_cmds = supplied_verifiers
    brief_path = getattr(args, "dispatch_brief", None)
    if not getattr(args, "dispatch", False) or brief_path is None:
        return
    _, authorized = _load_authorized_brief(pathlib.Path(brief_path).resolve(), repo_root)
    supplied_paths = tuple(getattr(args, "allow_paths", None) or ())
    if supplied_paths and supplied_paths != authorized.owned_scope:
        raise ValueError("--allow-path must exactly match DispatchBrief.owned_scope")
    verifier_ids = _verifier_ids(list(authorized.verification_commands), repo_root)
    unregistered = [
        command
        for command in verifier_ids
        if command not in local_config(repo_root).get("verifiers", {})
    ]
    if unregistered:
        raise ValueError(
            "DispatchBrief.verification_commands are not registered verifiers: "
            + ", ".join(unregistered)
        )
    if supplied_verifiers and supplied_verifiers != verifier_ids:
        raise ValueError("--verify-cmd must exactly match DispatchBrief.verification_commands")
    args.allow_paths = list(authorized.owned_scope)
    args.verify_cmds = verifier_ids
    args.dispatch_capabilities = list(authorized.capabilities)

def job_identity(args, repo_root, prompt, model) -> str | None:
    """Persist the authorized brief scope and capabilities with the job row."""
    if not getattr(args, "dispatch", False) or getattr(args, "dispatch_brief", None) is None:
        return None
    return json.dumps(
        {
            "owned_scope": list(getattr(args, "allow_paths", None) or []),
            "capabilities": list(getattr(args, "dispatch_capabilities", ())),
        }
    )
