_loader = types.ModuleType("mir.core.conductor.dispatch_brief")
_loader.load_dispatch_brief = load_dispatch_brief
_loader.render_dispatch_brief = render_dispatch_brief
sys.modules[_loader.__name__] = _loader
_authority = types.ModuleType("tools.mir_executor.brief_policy")
_authority.authorize_dispatch_brief = authorize_dispatch_brief
sys.modules[_authority.__name__] = _authority
